/**
 * The error vocabulary the app reasons about. Everything the API can go
 * wrong with arrives as one of these, so screens never inspect status codes.
 */

/** The RFC 7807 body the API returns for every failure. */
export interface Problem {
  type: string;
  title: string;
  status: number;
  detail?: string;
  instance?: string;
  /** A stable machine-readable code, such as `duplicate_headword`. */
  code?: string;
  errors?: Record<string, unknown>;
}

/** What went wrong, in terms the UI can act on. */
export type ApiErrorKind =
  /** No network, or the request never reached the server. Retry later. */
  | 'offline'
  /** The session is gone; sign in again. */
  | 'unauthenticated'
  /** Signed in, but not allowed to do this. */
  | 'forbidden'
  /** The thing is not there, or not visible to this user. */
  | 'notFound'
  /** The input was rejected; `problem.errors` may name the fields. */
  | 'invalid'
  /** Someone else changed it first, or it already exists. */
  | 'conflict'
  /** Rate limited or over quota; back off. */
  | 'tooMany'
  /**
   * Not a permission they lack: a thing they can buy. The app shows an
   * offer rather than an error, so it is its own kind.
   */
  | 'needsPayment'
  /** The server broke, or answered something unusable. */
  | 'server';

/** A failed API call. */
export class ApiError extends Error {
  readonly kind: ApiErrorKind;
  readonly status: number;
  readonly problem?: Problem;
  /**
   * How long the server asked us to wait before trying again (a 503 or 429
   * with `Retry-After`), in milliseconds. Absent when it asked for nothing.
   */
  readonly retryAfterMs?: number;

  constructor(kind: ApiErrorKind, message: string, status = 0, problem?: Problem, retryAfterMs?: number) {
    super(message);
    this.name = 'ApiError';
    this.kind = kind;
    this.status = status;
    if (problem) this.problem = problem;
    if (retryAfterMs !== undefined) this.retryAfterMs = retryAfterMs;
  }

  /** The stable code the API attached, when it sent one. */
  get code(): string | undefined {
    return this.problem?.code;
  }

  /** Whether retrying the same request unchanged could succeed. */
  get retryable(): boolean {
    return this.kind === 'offline' || this.kind === 'server' || this.kind === 'tooMany';
  }

  /**
   * Whether the server said it is overloaded and asked for a pause, rather
   * than refusing this request: the client then sets `retryAfterMs`.
   */
  get busy(): boolean {
    return this.retryAfterMs !== undefined;
  }
}

/** Maps a status code to the kind the UI reasons about. */
export function kindForStatus(status: number): ApiErrorKind {
  if (status === 401) return 'unauthenticated';
  if (status === 402) return 'needsPayment';
  if (status === 403) return 'forbidden';
  if (status === 404 || status === 410) return 'notFound';
  if (status === 409 || status === 422) return 'conflict';
  if (status === 429) return 'tooMany';
  if (status >= 500) return 'server';
  return 'invalid';
}

/** True when the value is an ApiError of the given kind. */
export function isApiError(error: unknown, kind?: ApiErrorKind): error is ApiError {
  return error instanceof ApiError && (kind === undefined || error.kind === kind);
}
